const express = require('express');
const diagnostics_channel = require('node:diagnostics_channel');
const { AsyncLocalStorage } = require('node:async_hooks');

const app = express();
const sessionContext = new AsyncLocalStorage();
const slowQueryChannel = diagnostics_channel.channel('orm:slow_query');

const slowQueryProfiles = new Map();

slowQueryChannel.subscribe((data) => {
  const store = sessionContext.getStore();
  slowQueryProfiles.set(data.profileId, {
    tenantId: store?.tenantId,
    durationMs: data.duration,
    planJson: data.executionPlan,
    tablesAccessed: data.tables
  });
});

app.use((req, res, next) => {
  const tenantId = req.header('X-Tenant-Identifier');
  sessionContext.run({ tenantId }, next);
});

app.get('/api/performance/slow-queries/:profileId', (req, res) => {
  const currentTenant = sessionContext.getStore()?.tenantId;
  const profile = slowQueryProfiles.get(req.params.profileId);

  if (!profile) {
    return res.status(404).json({ error: 'Profile not found' });
  }

  // Restrict execution plan inspection to the owning tenant
  if (!currentTenant || profile.tenantId !== currentTenant) {
    return res.status(403).json({ error: 'Access denied: slow query profile belongs to another tenant' });
  }

  res.json(profile);
});

app.listen(9104);
